import * as THREE from 'three';
import { buildWorld } from './world.js';
import { Enemy } from './enemy.js';
import { Weapon } from './weapon.js';
import {
  unlockAudio, playHitmarker, playPlayerHit, playEnemyShot,
  playFootstep, playRicochet,
} from './audio.js';

// ---------- Renderer / scene ----------
const renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: 'high-performance' });
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.05;
renderer.outputColorSpace = THREE.SRGBColorSpace;
document.getElementById('app').appendChild(renderer.domElement);

const scene = new THREE.Scene();
const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.01, 120);
camera.rotation.order = 'YXZ';
scene.add(camera);

const world = buildWorld(scene);
const weapon = new Weapon(camera);

window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
});

// ---------- Player state ----------
const HIP_FOV = 75, ADS_FOV = 52;
const EYE_STAND = 1.62, EYE_CROUCH = 1.08;

const player = {
  pos: world.playerSpawn.clone(),
  vel: new THREE.Vector3(),
  yaw: Math.PI / 2,
  pitch: 0,
  lean: 0,
  eyeHeight: EYE_STAND,
  hp: 100,
  regenDelay: 0,
  bobPhase: 0,
  stepDist: 0,
  alive: true,
};

const keys = {};
let mouseDX = 0, mouseDY = 0;
let firing = false, wantADS = false;

// ---------- Game state ----------
let gameState = 'menu'; // menu | playing | dead | win
let enemies = [];
const stats = { kills: 0, shots: 0, hits: 0, start: 0 };

function spawnEnemies() {
  for (const e of enemies) e.dispose();
  enemies = world.enemySpawns.map(s => new Enemy(scene, s));
}

function resetGame() {
  player.pos.copy(world.playerSpawn);
  player.vel.set(0, 0, 0);
  player.yaw = Math.PI / 2;
  player.pitch = 0;
  player.hp = 100;
  player.alive = true;
  weapon.mag = weapon.magSize;
  weapon.reserve = 120;
  weapon.reloading = 0;
  stats.kills = 0; stats.shots = 0; stats.hits = 0;
  stats.start = performance.now();
  for (const fx of effects) scene.remove(fx.obj);
  effects.length = 0;
  vignetteLevel = 0;
  spawnEnemies();
}

// ---------- Input ----------
window.addEventListener('keydown', e => {
  keys[e.code] = true;
  if (e.code === 'KeyR' && gameState === 'playing') weapon.startReload();
});
window.addEventListener('keyup', e => { keys[e.code] = false; });

document.addEventListener('mousemove', e => {
  if (document.pointerLockElement !== renderer.domElement) return;
  mouseDX += e.movementX;
  mouseDY += e.movementY;
});
document.addEventListener('mousedown', e => {
  if (document.pointerLockElement !== renderer.domElement) return;
  if (e.button === 0) firing = true;
  if (e.button === 2) wantADS = true;
});
document.addEventListener('mouseup', e => {
  if (e.button === 0) firing = false;
  if (e.button === 2) wantADS = false;
});
document.addEventListener('contextmenu', e => e.preventDefault());

// ---------- Screens / pointer lock ----------
const ui = {
  hud: document.getElementById('hud'),
  menu: document.getElementById('menu'),
  gameover: document.getElementById('gameover'),
  victory: document.getElementById('victory'),
  crosshair: document.getElementById('crosshair'),
  hitmarker: document.getElementById('hitmarker'),
  vignette: document.getElementById('vignette'),
  healthfill: document.getElementById('healthfill'),
  magcount: document.getElementById('magcount'),
  reservecount: document.getElementById('reservecount'),
  ammo: document.getElementById('ammo'),
  reloadhint: document.getElementById('reloadhint'),
  enemycount: document.getElementById('enemycount'),
  compassStrip: document.getElementById('compass-strip'),
  killfeed: document.getElementById('killfeed'),
};

// build compass strip: 3 repetitions of the 360° dial, 2px per degree
{
  const labels = { 0: 'N', 45: 'NE', 90: 'E', 135: 'SE', 180: 'S', 225: 'SW', 270: 'W', 315: 'NW' };
  let html = '';
  for (let d = 0; d < 1080; d += 15) {
    const deg = d % 360;
    const text = labels[deg] !== undefined ? labels[deg] : '·';
    html += `<span style="position:absolute;left:${d * 2}px;transform:translateX(-50%)">${text}</span>`;
  }
  ui.compassStrip.innerHTML = html;
}

function enterGame(reset) {
  unlockAudio();
  if (reset) resetGame();
  gameState = 'playing';
  ui.menu.classList.add('hidden');
  ui.gameover.classList.add('hidden');
  ui.victory.classList.add('hidden');
  ui.hud.classList.add('visible');
  renderer.domElement.requestPointerLock();
}

ui.menu.addEventListener('click', () => enterGame(stats.start === 0 || !player.alive ? true : false));
ui.gameover.addEventListener('click', () => enterGame(true));
ui.victory.addEventListener('click', () => enterGame(true));

document.addEventListener('pointerlockchange', () => {
  if (document.pointerLockElement !== renderer.domElement && gameState === 'playing') {
    gameState = 'menu';
    ui.menu.classList.remove('hidden');
    ui.hud.classList.remove('visible');
  }
});

// ---------- Effects ----------
const effects = []; // { obj, life, maxLife, update? }

function addTracer(from, to, color = 0xffe2a8) {
  const geo = new THREE.BufferGeometry().setFromPoints([from, to]);
  const mat = new THREE.LineBasicMaterial({
    color, transparent: true, opacity: 0.9, blending: THREE.AdditiveBlending, depthWrite: false,
  });
  const line = new THREE.Line(geo, mat);
  scene.add(line);
  effects.push({ obj: line, life: 0.07, maxLife: 0.07 });
}

function addImpact(point, normal) {
  const count = 6;
  const geo = new THREE.BufferGeometry();
  const positions = new Float32Array(count * 3);
  const velocities = [];
  for (let i = 0; i < count; i++) {
    positions[i * 3] = point.x; positions[i * 3 + 1] = point.y; positions[i * 3 + 2] = point.z;
    const v = normal.clone()
      .add(new THREE.Vector3((Math.random() - 0.5) * 1.6, Math.random() * 1.2, (Math.random() - 0.5) * 1.6))
      .multiplyScalar(2 + Math.random() * 2);
    velocities.push(v);
  }
  geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
  const pts = new THREE.Points(geo, new THREE.PointsMaterial({
    color: 0xc8bfae, size: 0.03, transparent: true, opacity: 0.9, depthWrite: false,
  }));
  scene.add(pts);
  effects.push({
    obj: pts, life: 0.4, maxLife: 0.4,
    update(dt) {
      const p = pts.geometry.attributes.position;
      for (let i = 0; i < count; i++) {
        velocities[i].y -= 9.8 * dt;
        p.array[i * 3] += velocities[i].x * dt;
        p.array[i * 3 + 1] += velocities[i].y * dt;
        p.array[i * 3 + 2] += velocities[i].z * dt;
      }
      p.needsUpdate = true;
    },
  });
  // small scorch mark
  const mark = new THREE.Mesh(
    new THREE.CircleGeometry(0.035, 8),
    new THREE.MeshBasicMaterial({ color: 0x14110e, transparent: true, opacity: 0.8 }));
  mark.position.copy(point).addScaledVector(normal, 0.004);
  mark.lookAt(point.clone().add(normal));
  scene.add(mark);
  effects.push({ obj: mark, life: 12, maxLife: 12 });
}

function addBlood(point) {
  const mist = new THREE.Mesh(
    new THREE.SphereGeometry(0.09, 8, 8),
    new THREE.MeshBasicMaterial({ color: 0x6e0d0d, transparent: true, opacity: 0.7, depthWrite: false }));
  mist.position.copy(point);
  scene.add(mist);
  effects.push({
    obj: mist, life: 0.25, maxLife: 0.25,
    update() { mist.scale.multiplyScalar(1.09); },
  });
}

// ---------- Shooting ----------
const raycaster = new THREE.Raycaster();
const _muzzle = new THREE.Vector3();
const _camDir = new THREE.Vector3();

weapon.onShot = (spread) => {
  stats.shots++;
  camera.getWorldDirection(_camDir);
  const dir = _camDir.clone();
  dir.x += (Math.random() - 0.5) * spread * 2;
  dir.y += (Math.random() - 0.5) * spread * 2;
  dir.z += (Math.random() - 0.5) * spread * 2;
  dir.normalize();

  raycaster.set(camera.getWorldPosition(new THREE.Vector3()), dir);
  raycaster.far = 100;

  const targets = [...world.solids.children];
  for (const e of enemies) if (e.alive) targets.push(...e.hitboxes);
  const hits = raycaster.intersectObjects(targets, false);

  weapon.muzzleWorldPos(_muzzle);
  let endPoint = raycaster.ray.at(100, new THREE.Vector3());

  if (hits.length > 0) {
    const hit = hits[0];
    endPoint = hit.point;
    const enemy = hit.object.userData.enemy;
    if (enemy) {
      stats.hits++;
      const headshot = hit.object.userData.part === 'head';
      const killed = enemy.takeDamage(headshot ? 100 : 34, player.pos);
      addBlood(hit.point);
      playHitmarker();
      flashHitmarker(killed);
      if (killed) {
        stats.kills++;
        addKillFeed(headshot ? 'HOSTILE DOWN — HEADSHOT' : 'HOSTILE DOWN');
        if (enemies.every(e => !e.alive)) endRound(true);
      }
    } else {
      const normal = hit.face
        ? hit.face.normal.clone().transformDirection(hit.object.matrixWorld)
        : dir.clone().negate();
      addImpact(hit.point, normal);
      if (Math.random() < 0.3) playRicochet(hit.distance);
    }
  }

  addTracer(_muzzle.clone(), endPoint);
  // gunfire attracts nearby patrolling hostiles
  for (const e of enemies) e.hearGunshot(player.pos);
};

let hitmarkerTimer = null;
function flashHitmarker(kill) {
  ui.hitmarker.style.opacity = 1;
  ui.hitmarker.classList.toggle('kill', kill);
  clearTimeout(hitmarkerTimer);
  hitmarkerTimer = setTimeout(() => { ui.hitmarker.style.opacity = 0; }, 120);
}

function addKillFeed(text) {
  const div = document.createElement('div');
  div.textContent = text;
  ui.killfeed.prepend(div);
  setTimeout(() => div.remove(), 4200);
  while (ui.killfeed.children.length > 5) ui.killfeed.lastChild.remove();
}

// ---------- Taking damage ----------
let vignetteLevel = 0;

function fireAtPlayer(enemy, hit, dist) {
  const from = enemy.muzzle.getWorldPosition(new THREE.Vector3());
  const chest = player.pos.clone().setY(player.pos.y + player.eyeHeight - 0.25);
  let to;
  if (hit) {
    to = chest;
    damagePlayer(6 + Math.random() * 8);
  } else {
    to = chest.clone().add(new THREE.Vector3(
      (Math.random() - 0.5) * 2.4, (Math.random() - 0.5) * 1.6, (Math.random() - 0.5) * 2.4));
  }
  addTracer(from, to, 0xffb09a);

  // stereo pan from direction relative to view
  const rel = from.clone().sub(camera.position).normalize();
  const right = new THREE.Vector3(1, 0, 0).applyQuaternion(camera.quaternion);
  playEnemyShot(dist, rel.dot(right));
}

function damagePlayer(amount) {
  if (!player.alive) return;
  player.hp -= amount;
  player.regenDelay = 5;
  vignetteLevel = Math.min(1, vignetteLevel + 0.45);
  playPlayerHit();
  if (player.hp <= 0) {
    player.hp = 0;
    player.alive = false;
    endRound(false);
  }
}

function endRound(won) {
  gameState = won ? 'win' : 'dead';
  document.exitPointerLock();
  ui.hud.classList.remove('visible');
  const secs = ((performance.now() - stats.start) / 1000).toFixed(1);
  const acc = stats.shots ? Math.round((stats.hits / stats.shots) * 100) : 0;
  const line = `${stats.kills} KILLS · ${acc}% ACCURACY · ${secs}s`;
  if (won) {
    document.getElementById('victory-stats').textContent = line;
    ui.victory.classList.remove('hidden');
  } else {
    document.getElementById('gameover-stats').textContent = line;
    ui.gameover.classList.remove('hidden');
  }
}

// ---------- Player movement ----------
function collides(x, z, eyeH) {
  const r = 0.35;
  for (const box of world.colliders) {
    if (x + r > box.min.x && x - r < box.max.x &&
        z + r > box.min.z && z - r < box.max.z &&
        box.min.y < eyeH + 0.2 && box.max.y > 0.15) return true;
  }
  return false;
}

function updatePlayer(dt) {
  // look
  const sens = 0.0021 * (1 - weapon.adsAmount * 0.45);
  player.yaw -= mouseDX * sens;
  player.pitch -= mouseDY * sens;

  // recoil
  if (weapon.recoilKick > 0) {
    player.pitch += weapon.recoilKick;
    player.yaw += (Math.random() - 0.5) * weapon.recoilKick * 0.5;
    weapon.recoilKick = 0;
  }
  player.pitch = THREE.MathUtils.clamp(player.pitch, -Math.PI / 2 + 0.05, Math.PI / 2 - 0.05);

  // lean
  let leanTarget = 0;
  if (keys.KeyQ) leanTarget = -1;
  else if (keys.KeyE) leanTarget = 1;
  player.lean += (leanTarget - player.lean) * Math.min(1, dt * 9);

  // crouch
  const crouching = !!(keys.KeyC || keys.ControlLeft);
  const targetEye = crouching ? EYE_CROUCH : EYE_STAND;
  player.eyeHeight += (targetEye - player.eyeHeight) * Math.min(1, dt * 10);

  // movement intent
  const fwd = (keys.KeyW ? 1 : 0) - (keys.KeyS ? 1 : 0);
  const strafe = (keys.KeyD ? 1 : 0) - (keys.KeyA ? 1 : 0);
  const sprinting = !!keys.ShiftLeft && fwd > 0 && !wantADS && !crouching;
  let speed = sprinting ? 5.4 : crouching ? 1.8 : 3.4;
  if (weapon.adsAmount > 0.5) speed *= 0.62;

  const sin = Math.sin(player.yaw), cos = Math.cos(player.yaw);
  const wishX = (-sin * fwd + cos * strafe);
  const wishZ = (-cos * fwd - sin * strafe);
  const len = Math.hypot(wishX, wishZ) || 1;
  const targetVX = (wishX / len) * speed * (fwd || strafe ? 1 : 0);
  const targetVZ = (wishZ / len) * speed * (fwd || strafe ? 1 : 0);
  player.vel.x += (targetVX - player.vel.x) * Math.min(1, dt * 11);
  player.vel.z += (targetVZ - player.vel.z) * Math.min(1, dt * 11);

  // collide & move, axis by axis
  const nx = player.pos.x + player.vel.x * dt;
  if (!collides(nx, player.pos.z, player.eyeHeight)) player.pos.x = nx;
  else player.vel.x = 0;
  const nz = player.pos.z + player.vel.z * dt;
  if (!collides(player.pos.x, nz, player.eyeHeight)) player.pos.z = nz;
  else player.vel.z = 0;

  // footsteps + head bob
  const hSpeed = Math.hypot(player.vel.x, player.vel.z);
  player.stepDist += hSpeed * dt;
  const stride = sprinting ? 2.2 : 1.7;
  if (player.stepDist > stride && hSpeed > 0.5) {
    player.stepDist = 0;
    playFootstep(sprinting);
  }
  player.bobPhase += hSpeed * dt * 1.6;
  const bob = Math.sin(player.bobPhase * 2) * 0.022 * Math.min(1, hSpeed / 3.4) * (1 - weapon.adsAmount * 0.7);

  // camera placement (lean offsets sideways + rolls)
  const leanOffset = 0.38 * player.lean;
  camera.position.set(
    player.pos.x + cos * leanOffset,
    player.pos.y + player.eyeHeight + bob,
    player.pos.z - sin * leanOffset);
  camera.rotation.set(player.pitch, player.yaw, -player.lean * 0.19, 'YXZ');

  // FOV blend for ADS + slight sprint FOV boost
  const targetFov = THREE.MathUtils.lerp(HIP_FOV, ADS_FOV, weapon.adsAmount) + (sprinting ? 4 : 0);
  if (Math.abs(camera.fov - targetFov) > 0.05) {
    camera.fov += (targetFov - camera.fov) * Math.min(1, dt * 12);
    camera.updateProjectionMatrix();
  }

  // health regen (slow, after 5s without damage)
  player.regenDelay -= dt;
  if (player.regenDelay <= 0 && player.hp < 100) {
    player.hp = Math.min(100, player.hp + dt * 4);
  }

  // weapon
  weapon.update(dt, {
    firing, wantADS, sprinting,
    moveSpeed: hSpeed,
    mouseDX, mouseDY,
  });

  mouseDX = 0;
  mouseDY = 0;
}

// ---------- HUD ----------
function updateHUD() {
  ui.healthfill.style.width = `${player.hp}%`;
  ui.healthfill.style.background = player.hp > 50
    ? 'linear-gradient(90deg,#57d973,#a8e063)'
    : player.hp > 25
      ? 'linear-gradient(90deg,#e0b builds,#e0bd5f)'.replace(' builds', 'bd5f') // gradient mid
      : 'linear-gradient(90deg,#e05548,#e07a5f)';
  ui.magcount.textContent = weapon.mag;
  ui.reservecount.textContent = `/ ${weapon.reserve}`;
  ui.ammo.classList.toggle('low', weapon.mag <= 7);
  ui.reloadhint.style.display = weapon.reloading > 0 ? 'block' : 'none';
  ui.crosshair.classList.toggle('ads', weapon.adsAmount > 0.6);
  ui.enemycount.textContent = enemies.filter(e => e.alive).length;

  // compass: middle copy of dial aligned to view heading
  let heading = THREE.MathUtils.radToDeg(-player.yaw) % 360;
  if (heading < 0) heading += 360;
  ui.compassStrip.style.transform = `translateX(${160 - (heading + 360) * 2}px)`;

  vignetteLevel = Math.max(0, vignetteLevel - 0.016);
  const hurt = 1 - player.hp / 100;
  ui.vignette.style.opacity = Math.min(1, vignetteLevel + hurt * 0.45);
}

// ---------- Main loop ----------
const clock = new THREE.Clock();
const enemyCtx = {
  playerEye: new THREE.Vector3(),
  playerPos: new THREE.Vector3(),
  solids: world.solids,
  colliders: world.colliders,
  fireAtPlayer,
  time: 0,
};

function animate() {
  requestAnimationFrame(animate);
  const dt = Math.min(clock.getDelta(), 0.05);
  const t = clock.elapsedTime;

  if (gameState === 'playing') {
    updatePlayer(dt);

    enemyCtx.playerEye.copy(camera.position);
    enemyCtx.playerPos.copy(player.pos);
    enemyCtx.time = t;
    for (const e of enemies) e.update(dt, enemyCtx);

    updateHUD();
  }

  // effects always tick so tracers don't freeze on screens
  for (let i = effects.length - 1; i >= 0; i--) {
    const fx = effects[i];
    fx.life -= dt;
    if (fx.update) fx.update(dt);
    if (fx.obj.material) fx.obj.material.opacity = Math.min(fx.obj.material.opacity ?? 1, fx.life / fx.maxLife);
    if (fx.life <= 0) {
      scene.remove(fx.obj);
      effects.splice(i, 1);
    }
  }

  // drifting dust in the light shaft
  const dustPos = world.dust.geometry.attributes.position;
  for (let i = 0; i < dustPos.count; i++) {
    let y = dustPos.getY(i) - dt * 0.06;
    if (y < 0) y = 4;
    dustPos.setY(i, y);
  }
  dustPos.needsUpdate = true;

  renderer.render(scene, camera);
}

spawnEnemies();
animate();
